script:
$env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
"=== checking .env ==="
Get-Content "C:\Users\E\AppData\Local\hermes\.env" | ForEach-Object { if ($_ -match "^(ZEN|OPENAI)_API_KEY=") { $_.Substring(0, 20) + "..." } }
"=== setting key directly in provider config ==="
$key = (Get-Content "C:\Users\E\AppData\Local\hermes\.env" | Select-String "ZEN_API_KEY=(.*)").Matches.Groups[1].Value.Trim()
hermes config set providers.zen.api_key $key 2>&1 | Select-Object -First 2
"=== testing ==="
$job = Start-Job -ScriptBlock {
  $env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
  hermes -z "Say HI" -m "space-bunny-free" --provider zen 2>&1 | Select-Object -First 10
}
if (Wait-Job $job -Timeout 60) {
  Receive-Job $job | Select-Object -First 10
} else {
  "TIMED OUT"
  Stop-Job $job
}
Remove-Job $job -Force
